CREATE TABLE IF NOT EXISTS battles (id TEXT PRIMARY KEY, chat_id TEXT NOT NULL, creator_id TEXT NOT NULL, state TEXT NOT NULL DEFAULT '{}', updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS members (battle_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'player', PRIMARY KEY(battle_id,user_id));
CREATE TABLE IF NOT EXISTS tokens (id TEXT PRIMARY KEY,battle_id TEXT NOT NULL,owner_id TEXT,name TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,emoji TEXT NOT NULL DEFAULT '⚔️');
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY,battle_id TEXT NOT NULL,token_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending');